def sha256_file(path):

    digest = hashlib.sha256()

    with open(
        path,
        "rb",
    ) as handle:

        while True:

            block = handle.read(
                1024 * 1024
            )

            if not block:

                break

            digest.update(
                block
            )

    return digest.hexdigest()


def mae(values):

    return float(
        np.mean(
            np.abs(
                np.asarray(
                    values,
                    dtype=np.float64,
                )
            )
        )
    )


def rms(values):

    values = np.asarray(
        values,
        dtype=np.float64,
    )

    return float(
        np.sqrt(
            np.mean(
                values ** 2
            )
        )
    )


def find_npz_key(
    data,
    aliases,
    description,
    required=True,
):

    lookup = {
        key.lower():
            key
        for key
        in data.files
    }

    for alias in aliases:

        if alias.lower() in lookup:

            return lookup[
                alias.lower()
            ]

    if required:

        raise KeyError(
            f"Could not identify {description}.\n"
            f"Accepted aliases: {aliases}\n"
            f"Available keys: {list(data.files)}"
        )

    return None


def save_csv(
    path,
    rows,
):

    if not rows:

        return

    with open(
        path,
        "w",
        newline="",
        encoding="utf-8",
    ) as handle:

        writer = csv.DictWriter(
            handle,
            fieldnames=list(
                rows[0].keys()
            ),
        )

        writer.writeheader()

        writer.writerows(
            rows
        )


# =============================================================================
# LOAD AND RECONCILE SG6 DATABASE
# =============================================================================

def load_sg6():

    if not SG6_FILE.exists():

        raise FileNotFoundError(
            "Missing V15-SG6 database:\n"
            f"{SG6_FILE}"
        )

    data = np.load(
        SG6_FILE,
        allow_pickle=True,
    )

    print(
        "\nSG6 DATABASE KEYS"
    )

    for key in data.files:

        print(
            f"  {key:28s} "
            f"{np.shape(data[key])}"
        )

    # =========================================================================
    # COMMON XI COORDINATE
    # =========================================================================

    xi_key = find_npz_key(
        data,
        [
            "xi",
            "xi_common",
            "common_xi",
            "XI",
        ],
        "common xi coordinate",
    )

    xi = np.asarray(
        data[xi_key],
        dtype=np.float64,
    )

    # =========================================================================
    # STREAMLINE SPATIAL COORDINATES
    #
    # SG6 authoritative field:
    #
    #       xyz_m
    #
    # Units: metres
    # =========================================================================

    xyz_key = find_npz_key(
        data,
        [
            "xyz_m",
            "transport_xyz",
            "xyz",
            "streamline_xyz",
            "XYZ",
        ],
        "streamline XYZ coordinates",
    )

    xyz = np.asarray(
        data[xyz_key],
        dtype=np.float64,
    )

    # =========================================================================
    # TIME OF FLIGHT
    #
    # SG6 authoritative field:
    #
    #       tau_s
    #
    # Units: seconds
    #
    # SG7C works internally in days because physical deployment times and
    # the SG7A/SG7B transport coordinate are expressed in days.
    # =========================================================================

    tof_key = find_npz_key(
        data,
        [
            "tau_s",
            "tof_s",
            "tof_days",
            "tof",
            "tau_days",
            "tau",
            "TOF",
        ],
        "streamline TOF array",
    )

    tof_raw = np.asarray(
        data[tof_key],
        dtype=np.float64,
    )

    if tof_key.lower() in {
        "tau_s",
        "tof_s",
    }:

        tof = (
            tof_raw
            /
            86400.0
        )

        tof_conversion = (
            "seconds -> days"
        )

    else:

        tof = tof_raw.copy()

        tof_conversion = (
            "stored as deployment units"
        )

    # =========================================================================
    # TERMINAL TOF
    #
    # SG6 authoritative field:
    #
    #       tau_end_s
    #
    # Units: seconds
    # =========================================================================

    tau_end_key = find_npz_key(
        data,
        [
            "tau_end_s",
            "terminal_tof_s",
            "tau_end_days",
            "tau_end",
            "terminal_tof_days",
            "terminal_tof",
        ],
        "terminal streamline TOF",
        required=False,
    )

    if tau_end_key is not None:

        tau_end_raw = np.asarray(
            data[tau_end_key],
            dtype=np.float64,
        ).reshape(-1)

        if tau_end_key.lower() in {
            "tau_end_s",
            "terminal_tof_s",
        }:

            tau_end = (
                tau_end_raw
                /
                86400.0
            )

            tau_end_conversion = (
                "seconds -> days"
            )

        else:

            tau_end = (
                tau_end_raw.copy()
            )

            tau_end_conversion = (
                "stored as deployment units"
            )

    else:

        tau_end = (
            tof[:, -1].copy()
        )

        tau_end_conversion = (
            "reconstructed from final TOF node"
        )

    # =========================================================================
    # STREAMLINE FLOW WEIGHTS
    #
    # SG6 authoritative field:
    #
    #       weights_m3_s
    #
    # Units: m^3/s
    #
    # SG7C reports and validates flow in m^3/day.
    # =========================================================================

    weight_key = find_npz_key(
        data,
        [
            "weights_m3_s",
            "weight_m3_s",
            "flow_weights_m3_s",
            "streamline_weights_m3_s",
            "weights_m3_day",
            "weight_m3_day",
            "flow_weights_m3_day",
            "streamline_weights_m3_day",
            "weights",
            "flow_weights",
        ],
        "streamline flow weights",
    )

    weights_raw = np.asarray(
        data[weight_key],
        dtype=np.float64,
    ).reshape(-1)

    if weight_key.lower() in {
        "weights_m3_s",
        "weight_m3_s",
        "flow_weights_m3_s",
        "streamline_weights_m3_s",
    }:

        weights = (
            weights_raw
            *
            86400.0
        )

        weight_conversion = (
            "m3/s -> m3/day"
        )

    else:

        weights = (
            weights_raw.copy()
        )

        weight_conversion = (
            "stored as deployment units"
        )

    # =========================================================================
    # PRODUCER LABELS
    # =========================================================================

    producer_key = find_npz_key(
        data,
        [
            "producer",
            "producers",
            "producer_name",
            "producer_names",
            "producer_label",
            "producer_labels",
            "capture_producer",
        ],
        "producer labels",
        required=False,
    )

    if producer_key is not None:

        producer_raw = np.asarray(
            data[producer_key]
        ).reshape(-1)

        producers = []

        for value in producer_raw:

            if isinstance(
                value,
                bytes,
            ):

                value = value.decode(
                    "utf-8"
                )

            producers.append(
                str(value)
            )

        producers = np.asarray(
            producers,
            dtype=object,
        )

    else:

        producers = np.asarray(
            [
                "UNKNOWN"
                for _ in range(
                    len(tau_end)
                )
            ],
            dtype=object,
        )

    # =========================================================================
    # STREAMLINE IDS
    # =========================================================================

    streamline_id_key = find_npz_key(
        data,
        [
            "streamline_id",
            "streamline_ids",
            "id",
            "ids",
        ],
        "streamline IDs",
        required=False,
    )

    if streamline_id_key is not None:

        streamline_id = np.asarray(
            data[streamline_id_key]
        ).reshape(-1)

    else:

        streamline_id = np.arange(
            len(tau_end),
            dtype=np.int64,
        )

    # =========================================================================
    # PATH LENGTH
    # =========================================================================

    path_length_key = find_npz_key(
        data,
        [
            "path_length_m",
            "path_length",
            "streamline_path_length_m",
        ],
        "streamline path length",
        required=False,
    )

    if path_length_key is not None:

        path_length = np.asarray(
            data[path_length_key],
            dtype=np.float64,
        )

    else:

        path_length = None

    # =========================================================================
    # INTERFACE DIAGNOSTICS
    # =========================================================================

    print(
        "\nSG6 -> SG7C FIELD MAPPING"
    )

    print(
        f"  xi                      : "
        f"{xi_key}"
    )

    print(
        f"  XYZ                     : "
        f"{xyz_key}"
    )

    print(
        f"  TOF                     : "
        f"{tof_key}"
    )

    print(
        f"  TOF conversion          : "
        f"{tof_conversion}"
    )

    print(
        f"  Terminal TOF            : "
        f"{tau_end_key if tau_end_key is not None else 'reconstructed'}"
    )

    print(
        f"  Terminal TOF conversion : "
        f"{tau_end_conversion}"
    )

    print(
        f"  Flow weights            : "
        f"{weight_key}"
    )

    print(
        f"  Weight conversion       : "
        f"{weight_conversion}"
    )

    print(
        f"  Producer                : "
        f"{producer_key if producer_key is not None else 'UNKNOWN'}"
    )

    print(
        f"  Streamline ID           : "
        f"{streamline_id_key if streamline_id_key is not None else 'generated'}"
    )

    # =========================================================================
    # INTERNAL SG6 CONSISTENCY CHECK
    # =========================================================================

    tau_terminal_difference = float(
        np.max(
            np.abs(
                tof[:, -1]
                -
                tau_end
            )
        )
    )

    print(
        "\nSG6 INTERNAL CONSISTENCY"
    )

    print(
        f"  max |tau[:,-1]-tau_end| : "
        f"{tau_terminal_difference:.6e} days"
    )

    return {
        "xi":
            xi,

        "xyz":
            xyz,

        "tof":
            tof,

        "tau_end":
            tau_end,

        "weights":
            weights,

        "producers":
            producers,

        "streamline_id":
            streamline_id,

        "path_length":
            path_length,

        "raw_keys":
            list(data.files),

        "source_xyz_key":
            xyz_key,

        "source_tof_key":
            tof_key,

        "source_tau_end_key":
            tau_end_key,

        "source_weight_key":
            weight_key,

        "tof_conversion":
            tof_conversion,

        "tau_end_conversion":
            tau_end_conversion,

        "weight_conversion":
            weight_conversion,

        "tau_terminal_difference_days":
            tau_terminal_difference,
    }


