def plot_representative_profiles(
    deployments,
    sg6,
):

    tau_end = (
        sg6[
            "tau_end"
        ]
    )

    percentiles = [
        10.0,
        50.0,
        90.0,
    ]

    indices = []

    for percentile in percentiles:

        target = np.percentile(
            tau_end,
            percentile,
        )

        index = int(
            np.argmin(
                np.abs(
                    tau_end
                    -
                    target
                )
            )
        )

        indices.append(
            index
        )

    for result in deployments:

        fig, ax = plt.subplots(
            figsize=(
                9,
                7,
            )
        )

        for index in indices:

            ax.plot(
                sg6[
                    "xi"
                ],
                result[
                    "truth"
                ][
                    index
                ],
                linewidth=2.0,
                label=(
                    "SG7A "
                    f"tau={tau_end[index]:.1f} d"
                ),
            )

            ax.plot(
                sg6[
                    "xi"
                ],
                result[
                    "pirnn"
                ][
                    index
                ],
                linestyle="--",
                linewidth=1.5,
                label=(
                    "PI-RNN "
                    f"tau={tau_end[index]:.1f} d"
                ),
            )

        ax.set_xlabel(
            r"$\xi$"
        )

        ax.set_ylabel(
            "Saturation"
        )

        ax.set_title(
            "PAD-Stream V15-SG7C\n"
            f"Representative SGSim Streamlines — "
            f"{result['physical_time_days']:.0f} days"
        )

        ax.legend(
            fontsize=8,
            ncol=2,
        )

        fig.tight_layout()

        fig.savefig(
            OUTPUT_DIR
            /
            (
                "V15SG7C_Streamline_Profiles_"
                f"{int(result['physical_time_days'])}d.png"
            ),
            dpi=300,
        )

        plt.close(
            fig
        )


